const mongoose = require('mongoose');
const { DEVICE_STATUS } = require('../config/constants');

const deviceSchema = new mongoose.Schema(
  {
    // Android device id used as the stable identifier from the APK.
    deviceId: { type: String, default: '', unique: true, index: true },
    // Opaque token the device presents on the deviceToken header to post events.
    deviceToken: { type: String, default: '', index: true },
    // Short human-typeable pairing code generated by the trader panel before
    // a phone exists, and consumed by /register-device to claim this row.
    licenseKey: { type: String, default: '', index: true },
    // Pairing code expiry (5 min from generation). Only meaningful while
    // status === PENDING — /register-device rejects a claim attempt past
    // this, whether it's a fresh scan or a retry against a stale code.
    licenseExpiresAt: { type: Date, default: null },
    // DEPRECATED (2026-08-06): superseded by traderId below, which is the
    // real authorization boundary now. NOT dead — still read by apk.js
    // (stamped onto RawEvent.ngoId, and copied onto DebitSMS/OutgoingPayment)
    // to feed the not-yet-retired donation-ledger matching path
    // (matchingEngine.checkMatch). Do not drop without first retiring/
    // rekeying that.
    ngoId: {
      type: mongoose.Schema.Types.ObjectId,
      ref: 'NGO',
      default: null,
      index: true,
    },
    // The real trader (MySQL trader.id) who generated this device's pairing
    // code — the actual authorization boundary going forward, same as
    // Account.traderId.
    traderId: {
      type: Number,
      default: null,
      index: true,
    },
    // Third status field, separate from the lastSeen-derived `online` check
    // (routes/apk.js's isOnline()) — reported by HeartbeatService from
    // ListenerHealthStore, itself set by NotificationService's
    // onListenerConnected/onListenerDisconnected. null = never reported
    // (older APK build predating this field, or no heartbeat yet) — must
    // stay distinct from `false` so the trader panel doesn't show "degraded"
    // for a device that simply hasn't said anything either way.
    listenerConnected: { type: Boolean, default: null },
    // FEATURE 2 — Payout evidence capture. Phase 1a (Scenario 10): a trader can
    // have up to 3 payouts in processing at once and complete ANY of them on
    // ANY of their linked devices, so this is a LIST (capped at 3), not a single
    // overwritable slot. Each entry carries the payout's full identity so the
    // device can match a success screen / debit SMS to the RIGHT one. Set via
    // POST /api/internal/set-active-payout[-for-trader] (replace/prune by
    // orderId) and mirrored down to the device on every heartbeat — see
    // routes/apk.js. Semantics live in services/payoutList.js.
    activePayouts: {
      type: [
        {
          _id: false,
          orderId: { type: String, required: true },
          payeeName: { type: String, default: '' },
          accountNumber: { type: String, default: '' },
          ifsc: { type: String, default: '' },
          amount: { type: String, default: '' },
          activatedAt: { type: Date, default: Date.now },
        },
      ],
      default: [],
    },
    deviceModel: { type: String, default: '' },
    // Trader-assigned display name (set via SetDeviceNameActivity), distinct
    // from deviceModel (the hardware model string).
    deviceName: { type: String, default: '' },
    androidVersion: { type: String, default: '' },
    appVersion: { type: String, default: '' },
    status: {
      type: String,
      enum: Object.values(DEVICE_STATUS),
      default: DEVICE_STATUS.ACTIVE,
    },
    lastSeen: { type: Date, default: Date.now },
    createdAt: { type: Date, default: Date.now },
  },
  { timestamps: true }
);

module.exports = mongoose.model('Device', deviceSchema);
